curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(first: 20, filter: { title: { contains: "Checkout crash on Safari" } }) { nodes { id identifier title estimate url description comments(first: 50) { nodes { id body user { name email } createdAt attachments { id url name } } } labels { nodes { name } } } } }"
  }'
